-- =====================================================================
-- V21: Cơ sở dữ liệu dinh dưỡng thực phẩm
-- Additive: chỉ tạo bảng mới, không đụng bảng nào đang có.
-- Mọi giá trị dinh dưỡng tính TRÊN 100 g phần ăn được.
-- =====================================================================

CREATE TABLE nutrition_foods (
    id BIGINT PRIMARY KEY,
    source VARCHAR(30) NOT NULL,
    source_version VARCHAR(30) NOT NULL,
    source_food_code VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    name_vi VARCHAR(255),
    category VARCHAR(160),
    energy_kcal NUMERIC(10, 3),
    protein_g NUMERIC(10, 3),
    carbohydrate_g NUMERIC(10, 3),
    fiber_g NUMERIC(10, 3),
    sugars_g NUMERIC(10, 3),
    fat_total_g NUMERIC(10, 3),
    fat_saturated_g NUMERIC(10, 3),
    fat_monounsaturated_g NUMERIC(10, 3),
    fat_polyunsaturated_g NUMERIC(10, 3),
    cholesterol_mg NUMERIC(10, 3),
    sodium_mg NUMERIC(10, 3),
    potassium_mg NUMERIC(10, 3),
    magnesium_mg NUMERIC(10, 3),
    caffeine_mg NUMERIC(10, 3),
    alcohol_g NUMERIC(10, 3),
    vitamin_k_mcg NUMERIC(10, 3),
    epa_g NUMERIC(10, 3),
    dha_g NUMERIC(10, 3),
    created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ,
    created_by VARCHAR(255), updated_by VARCHAR(255),
    CONSTRAINT uq_nutrition_food_source_code UNIQUE (source, source_food_code)
);

COMMENT ON TABLE nutrition_foods IS 'Thanh phan dinh duong thuc pham, gia tri tren 100 g phan an duoc';
COMMENT ON COLUMN nutrition_foods.id IS 'Du lieu FNDDS: bang fdcId cua USDA. Du lieu tu tao: Snowflake ID';
COMMENT ON COLUMN nutrition_foods.source_food_code IS 'Ma mon cua nguon (FNDDS foodCode), Frontend goi la sourceFoodCode';

CREATE INDEX idx_nutrition_food_name_lower ON nutrition_foods (lower(name));
CREATE INDEX idx_nutrition_food_name_vi_lower ON nutrition_foods (lower(name_vi));
CREATE INDEX idx_nutrition_food_category ON nutrition_foods (category);
-- Tìm theo từ khóa bằng full-text có sẵn của PostgreSQL (không cần cài extension).
CREATE INDEX idx_nutrition_food_name_fts ON nutrition_foods USING GIN (to_tsvector('english', name));

CREATE TABLE nutrition_food_portions (
    id BIGINT PRIMARY KEY,
    food_id BIGINT NOT NULL REFERENCES nutrition_foods(id) ON DELETE CASCADE,
    sequence_number INTEGER NOT NULL,
    description VARCHAR(160) NOT NULL,
    gram_weight NUMERIC(10, 2) NOT NULL CHECK (gram_weight > 0),
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ,
    created_by VARCHAR(255), updated_by VARCHAR(255)
);

COMMENT ON TABLE nutrition_food_portions IS 'Khau phan thuong dung cua tung mon, quy doi ra gram';
COMMENT ON COLUMN nutrition_food_portions.id IS 'Du lieu FNDDS: fdcId * 1000 + thu tu. Du lieu tu tao: Snowflake ID';
COMMENT ON COLUMN nutrition_food_portions.is_default IS 'Khau phan nguon dung khi khong ro so luong';

CREATE INDEX idx_nutrition_food_portion_food ON nutrition_food_portions (food_id);

